package app.truemotion.vector;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.*;import android.net.*;import java.io.*;import java.util.*;
/** Native media files with a small asynchronous preview cache. */
final class VectorMedia {
 static final Map<VectorEditor,Integer> lastFrame=new WeakHashMap<VectorEditor,Integer>();
 static final Map<VectorEditor,Map<String,MediaPlayer>> players=new WeakHashMap<VectorEditor,Map<String,MediaPlayer>>();
 static final Map<VectorCanvas,LinkedHashMap<String,Bitmap>> frames=new WeakHashMap<VectorCanvas,LinkedHashMap<String,Bitmap>>();
 static final Set<String> requests=new HashSet<String>();static final java.util.concurrent.ExecutorService decoder=java.util.concurrent.Executors.newSingleThreadExecutor();
 static void importFile(Activity picker,VectorEditor e,Uri uri,int mode,Runnable done)throws Exception{if(mode==VectorFileActivity.PHOTO&&MediaCompat.isGif(picker,uri)){MediaCompat.vectorGif(picker,e,uri,done);return;}VectorDocument.Shape s=new VectorDocument.Shape();VectorImage photo=null;File media=null;s.x=e.doc.width/2d;s.y=e.doc.height/2d;s.name=mode==VectorFileActivity.PHOTO?L10n.t("Фото"):mode==VectorFileActivity.VIDEO?L10n.t("Видео"):L10n.t("Звук");if(mode==VectorFileActivity.PHOTO){photo=VectorRaster.image(VectorMediaIO.bytes(picker,uri,64*1024*1024));s.image=photo.id;s.imageFrame=new int[]{photo.width,photo.height,0,0};s.imageRect=new int[]{0,0,photo.width,photo.height};}else{media=VectorMediaIO.copy(picker,uri);try{MediaMetadataRetriever retriever=new MediaMetadataRetriever();try{retriever.setDataSource(media.getAbsolutePath());s.mediaDuration=Integer.parseInt(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(s.mediaDuration<1)throw new IOException("No media duration");if(mode==VectorFileActivity.VIDEO){int w=Integer.parseInt(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH)),h=Integer.parseInt(retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT));String rotation=retriever.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);if("90".equals(rotation)||"270".equals(rotation)){int q=w;w=h;h=q;}s.imageFrame=new int[]{w,h,0,0};}else s.imageFrame=new int[]{160,60,0,0};}finally{retriever.release();}s.mediaUri=Uri.fromFile(media).toString();s.mediaType=mode==VectorFileActivity.VIDEO?"video":"audio";s.mediaStart=e.doc.time(e.frame);}catch(Exception ex){media.delete();throw ex;}}
  if(!s.isAudio())s.sx=s.sy=Math.min(1,Math.min(e.doc.width/(double)s.imageFrame[0],e.doc.height/(double)s.imageFrame[1]));final VectorImage image=photo;picker.runOnUiThread(()->{done.run();e.snapshot();if(image!=null)e.doc.images.put(image.id,image);VectorDocument.Track t=new VectorDocument.Track(s.name);if(e.frame>0)t.keys.put(e.frame,new VectorDocument.Cel());t.keys.get(e.frame).shapes.add(s);if(s.isMedia()){int end=(int)Math.ceil((s.mediaStart+s.mediaDuration)*e.doc.fps/1000);e.doc.frames=Math.max(e.doc.frames,end);t.keys.put(end,new VectorDocument.Cel());}e.doc.tracks.add(t);e.track=e.doc.tracks.size()-1;e.selected.clear();e.selected.add(s.id);e.refresh();});
 }
 static void draw(VectorCanvas renderer,Canvas c,VectorDocument.Shape s,VectorDocument d,int frame,int tint){if(s.isAudio()){renderer.paint.setColor(0xff477eaa);c.drawRoundRect(new RectF(-80,-30,80,30),8,8,renderer.paint);renderer.paint.setColor(Color.WHITE);renderer.paint.setTextSize(18);renderer.paint.setTextAlign(Paint.Align.CENTER);c.drawText(L10n.t("Звук"),0,7,renderer.paint);return;}int time=Math.max(0,d.time(frame)-s.mediaStart)+s.mediaOffset;if(time>=s.mediaDuration+s.mediaOffset)return;String key=s.mediaUri+":"+time;Bitmap bitmap; synchronized(frames){LinkedHashMap<String,Bitmap> cache=frames.get(renderer);if(cache==null){cache=new LinkedHashMap<String,Bitmap>(8,.75f,true);frames.put(renderer,cache);}bitmap=cache.get(key);if(bitmap==null&&!requests.contains(key)&&requests.size()<3){requests.add(key);decoder.execute(()->{Bitmap result=null;try{MediaMetadataRetriever r=new MediaMetadataRetriever();try{r.setDataSource(Uri.parse(s.mediaUri).getPath());result=android.os.Build.VERSION.SDK_INT>=27?r.getScaledFrameAtTime(time*1000L,MediaMetadataRetriever.OPTION_CLOSEST,512,512):r.getFrameAtTime(time*1000L,MediaMetadataRetriever.OPTION_CLOSEST);}finally{r.release();}}catch(Exception error){android.util.Log.w("TrueVector","Media preview",error);}synchronized(frames){requests.remove(key);LinkedHashMap<String,Bitmap> target=frames.get(renderer);if(result!=null){if(target==null)result.recycle();else{target.put(key,result);while(target.size()>6){String first=target.keySet().iterator().next();target.remove(first);}}}}if(renderer.redraw!=null)new android.os.Handler(android.os.Looper.getMainLooper()).post(renderer.redraw);});}if(bitmap==null&&!cache.isEmpty())bitmap=cache.values().iterator().next();}
  if(bitmap!=null){renderer.paint.setAlpha((int)(s.opacity*255));renderer.paint.setFilterBitmap(true);c.drawBitmap(bitmap,null,new RectF(-s.imageFrame[0]/2f,-s.imageFrame[1]/2f,s.imageFrame[0]/2f,s.imageFrame[1]/2f),renderer.paint);renderer.paint.setAlpha(255);}
 }
 static void play(VectorEditor e){stop(e);Map<String,MediaPlayer> map=players.get(e);if(map==null){map=new LinkedHashMap<String,MediaPlayer>();players.put(e,map);}update(e);}
 static void update(VectorEditor e){Map<String,MediaPlayer> map=players.get(e);if(map==null){map=new LinkedHashMap<String,MediaPlayer>();players.put(e,map);}if(!e.playing)return;Integer previous=lastFrame.put(e,e.frame);if(previous!=null&&e.frame<previous)stop(e);Set<String> active=new HashSet<String>();for(VectorDocument.Shape s:e.doc.poseFrame(e.frame))if(s.isMedia()&&e.doc.time(e.frame)>=s.mediaStart&&e.doc.time(e.frame)<s.mediaStart+s.mediaDuration){active.add(s.id);if(!map.containsKey(s.id)){MediaPlayer p=new MediaPlayer();map.put(s.id,p);try{p.setDataSource(e.activity,Uri.parse(s.mediaUri));p.setVolume((float)s.opacity,(float)s.opacity);p.setOnPreparedListener(q->{if(e.playing&&players.get(e)!=null&&players.get(e).get(s.id)==q){int t=Math.max(0,e.doc.time(e.frame)-s.mediaStart)+s.mediaOffset;if(android.os.Build.VERSION.SDK_INT>=26)q.seekTo(t,MediaPlayer.SEEK_CLOSEST);else q.seekTo(t);q.start();}});p.prepareAsync();}catch(Exception error){map.remove(s.id);p.release();android.util.Log.w("TrueVector","Media audio",error);}}}for(Iterator<Map.Entry<String,MediaPlayer>> it=map.entrySet().iterator();it.hasNext();){Map.Entry<String,MediaPlayer> p=it.next();if(!active.contains(p.getKey())){p.getValue().release();it.remove();}}}
 static void stop(VectorEditor e){Map<String,MediaPlayer> map=players.get(e);if(map!=null){for(MediaPlayer p:map.values())p.release();map.clear();}}
 static void release(VectorEditor e){stop(e);players.remove(e);lastFrame.remove(e);synchronized(frames){LinkedHashMap<String,Bitmap> cache=frames.remove(e.stage.renderer);if(cache!=null)cache.clear();}}
}
